import { writeFile } from 'node:fs/promises';
import openapiTS, { astToString } from 'openapi-typescript';
import ts from 'typescript';

const openApiDocument = new URL('../../../apps/api/openapi/openapi.json', import.meta.url);
const outputFile = new URL('../src/schema.d.ts', import.meta.url);

const schema = await openapiTS(openApiDocument, {
  transform(schemaObject) {
    if (schemaObject.type === 'string' && schemaObject.format === 'binary') {
      return ts.factory.createTypeReferenceNode('Blob');
    }
    return undefined;
  },
});

const banner = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

await writeFile(outputFile, `${banner}${astToString(schema)}`, 'utf8');
